		condensed, err = buildCondensedCompactTranscriptEntries(transcriptBytes)
	}
	if err != nil || len(condensed) == 0 {
		return nil
	}

	var prompts []string
	for _, entry := range condensed {
		if entry.Type == summarize.EntryTypeUser && entry.Content != "" {
