			stopLoad(false)
			return fmt.Errorf("open checkpoint store: %w", openErr)
		}
		lookup.store = reopened.Persistent
		content, err = checkpoint.ReadLatestSessionContent(ctx, lookup.store, fullCheckpointID, summary)
