func transcriptTexts(raw []byte) []string {
	var texts []string
	for _, line := range strings.Split(string(raw), "\n") {
		var v any
		if json.Unmarshal([]byte(line), &v) != nil { continue }
		collectText(v, &texts)
	}
	return uniqueStrings(texts)
