			b.bundle.Warnings = append(b.bundle.Warnings, Warning{Text: "Graph evidence unavailable for " + s.name + ".", EvidenceIDs: []string{id}})
			continue
		}
		confidence := "potential"; if strings.Contains(strings.ToLower(string(out)), "partial") || strings.Contains(strings.ToLower(string(out)), "warning") { confidence = "question" }
		id := b.evidence("graph_impact", "symbol:"+s.file+":"+s.name, []string{"entire", "graph", "impact", "--repo", root, "--symbol", s.name, "--depth", "1", "--limit", "10", "--format", "json"}, string(out), confidence)
		b.bundle.PotentiallyAffected = append(b.bundle.PotentiallyAffected, Claim{Text: "Potential static impact for " + s.name + " in " + s.file + ".", EvidenceIDs: []string{diffID, id}, Confidence: confidence})
	}
}

func validateBundle(bundle ReviewBundle) error {
	evidence := map[string]bool{}; for _, e := range bundle.Evidence { if e.ID == "" || evidence[e.ID] { return errors.New("invalid evidence IDs") }; evidence[e.ID] = true }
	claims := append([]Claim{bundle.Overview}, bundle.Requested...); claims = append(claims, bundle.Implemented...); claims = append(claims, bundle.MissingOrUncertain...); claims = append(claims, bundle.PotentiallyAffected...); claims = append(claims, bundle.Continuation...)
	for _, c := range claims { if strings.TrimSpace(c.Text) == "" || len(c.EvidenceIDs) == 0 { return errors.New("every factual claim must reference evidence") }; for _, id := range c.EvidenceIDs { if !evidence[id] { return fmt.Errorf("claim references unknown evidence %s", id) } } }
	return nil
}

func renderText(b ReviewBundle) string {
	var out strings.Builder
	fmt.Fprintf(&out, "Entire Echo review\n\n%s\n", b.Overview.Text)
	for _, section := range []struct{name string; claims []Claim}{{"Requested", b.Requested}, {"Implemented", b.Implemented}, {"Missing or uncertain", b.MissingOrUncertain}, {"Potentially affected", b.PotentiallyAffected}, {"Continuation", b.Continuation}} {
		fmt.Fprintf(&out, "\n%s:\n", section.name); if len(section.claims) == 0 { out.WriteString("- None established by available evidence.\n") }; for _, c := range section.claims { fmt.Fprintf(&out, "- %s [evidence: %s]\n", c.Text, strings.Join(c.EvidenceIDs, ", ")) }
	}
	if len(b.Warnings) > 0 { out.WriteString("\nWarnings:\n"); for _, w := range b.Warnings { fmt.Fprintf(&out, "- %s [evidence: %s]\n", w.Text, strings.Join(w.EvidenceIDs, ", ")) } }
	out.WriteString("\nEvidence:\n"); for _, e := range b.Evidence { fmt.Fprintf(&out, "- %s (%s): %s\n", e.ID, e.Kind, e.Locator) }
	return out.String()
}

func main() {
	jsonOutput := flag.Bool("json", false, "write the versioned ReviewBundle JSON")
	flag.Parse()
	if flag.NArg() != 1 { fmt.Fprintln(os.Stderr, "usage: entire-echo [--json] <checkpoint-id-or-commit>"); os.Exit(2) }
	bundle, err := build(context.Background(), execRunner{}, mustGetwd(), flag.Arg(0))
	if err != nil { fmt.Fprintln(os.Stderr, "entire echo:", err); os.Exit(1) }
	if *jsonOutput { data, _ := json.MarshalIndent(bundle, "", "  "); fmt.Println(string(data)); return }
	fmt.Print(renderText(bundle))
}

func mustGetwd() string { wd, err := os.Getwd(); if err != nil { return "." }; return wd }

